import csv
from collections import Counter, defaultdict

rows = []
with open('benchmark/data.csv', newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append(row)

# Back-to-back wins detail
composer_years = defaultdict(list)
for row in rows:
    composer_years[row['Composer']].append(int(row['Year']))

# Check for 3+ wins composers and their dominance
print("Composers with 3+ wins and their win percentages by era:")
for comp in ['John Barry', 'John Williams', 'Ludwig Göransson', 'Max Steiner', 'Dimitri Tiomkin', 'Maurice Jarre', 'Alan Menken']:
    years = sorted(composer_years[comp])
    print(f"{comp}: {years}")

# First-time winner timeline
print("\nFirst-time winners by year:")
seen = set()
for row in rows:
    c = row['Composer']
    if c not in seen:
        print(f"  {row['Year']}: {c} ({row['Film']})")
        seen.add(c)

# Streaks / clusters
print("\nRepeat winner clusters:")
for i in range(1, len(rows)):
    if rows[i]['Composer'] == rows[i-1]['Composer']:
        print(f"  Back-to-back: {rows[i]['Year']} {rows[i]['Composer']}")

# Check if any composer won 3 in a row
for comp, years in composer_years.items():
    sy = sorted(years)
    for i in range(len(sy)-2):
        if sy[i+1] == sy[i]+1 and sy[i+2] == sy[i]+2:
            print(f"  THREE IN A ROW: {comp} {sy[i]}-{sy[i+2]}")

# 1980s detail
print("\n1980s winners:")
for row in rows:
    if 1980 <= int(row['Year']) <= 1989:
        print(f"  {row['Year']}: {row['Composer']} - {row['Film']}")

# 2020s detail
print("\n2020s winners:")
for row in rows:
    if 2020 <= int(row['Year']) <= 2029:
        print(f"  {row['Year']}: {row['Composer']} - {row['Film']}")

# Era repeat rates
def era(year):
    if year <= 1960:
        return "Golden Age"
    elif year <= 1980:
        return "Silver Age"
    elif year <= 2000:
        return "Modern"
    else:
        return "Contemporary"

era_rows = defaultdict(list)
for row in rows:
    era_rows[era(int(row['Year']))].append(row)

for e in ["Golden Age", "Silver Age", "Modern", "Contemporary"]:
    seen = set()
    repeats = 0
    total = len(era_rows[e])
    for row in era_rows[e]:
        c = row['Composer']
        if c in seen:
            repeats += 1
        else:
            seen.add(c)
    print(f"{e}: {repeats}/{total} repeat rate = {repeats/total*100:.1f}%")

